$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$runner=Get-Content -LiteralPath(Join-Path $PSScriptRoot 'run-kubernetes-bootstrap-observability-diagnostic.ps1')-Raw
foreach($x in @("ConfirmImpact='Low'","DiagnosticId='ob-k8s-bootstrap-observe-001'",'explicit_bootstrap_observability_approval_required','working_tree_not_clean','immutable_diagnostic_output_exists','profile_container_not_stopped','--kubernetes-version=v1.34.0','--cpus=4','--memory=6144mb','--disk-size=32g','--container-runtime=containerd','timeout_seconds=420','poll_seconds=5','kubelet-journal-capture.json','containerd-journal-capture.json','cri-control-plane-capture.json','profile_deleted=$false','application_manifest_applied=$false','workload_started=$false','toxic_created=$false','scientific_fault_started=$false','minikubeExe stop','seal-diagnostic-artifacts.ps1','verify-kubernetes-bootstrap-observability-diagnostic.ps1')){if(-not$runner.Contains($x)){throw "bootstrap_observability_runner_contract_missing:$x"}}
if($runner.Contains("ConfirmImpact='High'")){throw 'bootstrap_observability_interactive_confirmation_regression'}
foreach($forbidden in @('minikube delete','apply -k','config\online-boutique','manage-network-delay-proxy','toxic add')){if($runner.Contains($forbidden)){throw "bootstrap_observability_forbidden_scope:$forbidden"}}
$verifier=Get-Content -LiteralPath(Join-Path $PSScriptRoot 'verify-kubernetes-bootstrap-observability-diagnostic.ps1')-Raw
foreach($x in @('P2-KUBERNETES-BOOTSTRAP-OBS-DIAG-001','bootstrap_start_failed_with_live_evidence','live_bootstrap_evidence_missing','host_health_gate_failed')){if(-not$verifier.Contains($x)){throw "bootstrap_observability_verifier_contract_missing:$x"}}
Write-Output 'kubernetes_bootstrap_observability_contract_tests=passed'
